// Package warehouse tracks stock for a small warehouse.
package warehouse

import (
	"fmt"
	"sort"
)

// MaxItems caps how much one warehouse may hold.
const MaxItems = 500

// DefaultWarehouse is used when no warehouse is named.
const DefaultWarehouse = "main"

// ReorderThresholds are per-category because bolts and lathes do not move
// at remotely the same rate.
var ReorderThresholds = map[string]int{
	"fastener":   250,
	"tool":       5,
	"consumable": 40,
}

// Item is a single stocked item.
type Item struct {
	SKU      string
	Category string
	Quantity int
}

// NeedsReorder reports whether the item fell under its category threshold.
func (i Item) NeedsReorder() (bool, error) {
	threshold, ok := ReorderThresholds[i.Category]
	if !ok {
		// An unknown category is a data error, not a reason to reorder.
		return false, nil
	}
	if i.Quantity < 0 {
		return false, fmt.Errorf("%s has a negative quantity", i.SKU)
	}
	return i.Quantity < threshold, nil
}

// Inventory is the stock held in one warehouse.
type Inventory struct {
	Warehouse string
	items     map[string]Item
	history   []string
}

// NewInventory starts an empty inventory for a warehouse.
func NewInventory(warehouse string) *Inventory {
	if warehouse == "" {
		warehouse = DefaultWarehouse
	}
	return &Inventory{
		Warehouse: warehouse,
		items:     map[string]Item{},
		history:   nil,
	}
}

// Add stores an item, refusing to exceed the per-warehouse ceiling.
func (inv *Inventory) Add(item Item) error {
	if len(inv.items) >= MaxItems {
		return fmt.Errorf("%s already holds %d items", inv.Warehouse, MaxItems)
	}
	if existing, ok := inv.items[item.SKU]; ok {
		merged := Item{
			SKU:      item.SKU,
			Category: item.Category,
			Quantity: existing.Quantity + item.Quantity,
		}
		inv.items[item.SKU] = merged
		inv.history = append(inv.history, "merge "+item.SKU)
		return nil
	}
	inv.items[item.SKU] = item
	inv.history = append(inv.history, "add "+item.SKU)
	return nil
}

// Remove deletes an item by SKU and returns it.
func (inv *Inventory) Remove(sku string) (Item, error) {
	item, ok := inv.items[sku]
	if !ok {
		return Item{}, fmt.Errorf("%q is not stocked in %s", sku, inv.Warehouse)
	}
	delete(inv.items, sku)
	inv.history = append(inv.history, "remove "+sku)
	return item, nil
}

// ReorderList returns every item that fell under its threshold.
func (inv *Inventory) ReorderList() ([]Item, error) {
	var out []Item
	for _, item := range inv.items {
		due, err := item.NeedsReorder()
		if err != nil {
			return nil, err
		}
		if due {
			out = append(out, item)
		}
	}
	sort.Slice(out, func(a, b int) bool { return out[a].SKU < out[b].SKU })
	return out, nil
}

// AuditTrail renders the mutation history oldest first.
func (inv *Inventory) AuditTrail() []string {
	rendered := make([]string, 0, len(inv.history))
	for index, entry := range inv.history {
		rendered = append(rendered, fmt.Sprintf("%03d %s", index+1, entry))
	}
	return rendered
}

// Package warehouse: price calculation with tiered discounts.
package warehouse

import (
	"fmt"
	"math"
	"sort"
)

// BaseMarkup is applied to every cost price before discounts.
const BaseMarkup = 1.35

// Currency is the only currency this book quotes in.
const Currency = "EUR"

// Tier names a customer pricing tier.
type Tier string

// The tiers the business sells at.
const (
	TierRetail    Tier = "retail"
	TierTrade     Tier = "trade"
	TierWholesale Tier = "wholesale"
)

var discounts = map[Tier]float64{
	TierRetail:    0.0,
	TierTrade:     0.10,
	TierWholesale: 0.22,
}

// PriceBook holds cost prices keyed by SKU.
type PriceBook struct {
	costs map[string]float64
}

// NewPriceBook copies the cost table so callers cannot mutate it later.
func NewPriceBook(costs map[string]float64) (*PriceBook, error) {
	copied := make(map[string]float64, len(costs))
	for sku, cost := range costs {
		if cost < 0 {
			return nil, fmt.Errorf("negative cost price for %q", sku)
		}
		copied[sku] = cost
	}
	return &PriceBook{costs: copied}, nil
}

// CostOf returns the cost price for a SKU.
func (p *PriceBook) CostOf(sku string) (float64, error) {
	cost, ok := p.costs[sku]
	if !ok {
		return 0, fmt.Errorf("no cost price recorded for %q", sku)
	}
	return cost, nil
}

// Quote prices a line at a tier.
func (p *PriceBook) Quote(sku string, tier Tier, quantity int) (float64, error) {
	if quantity < 1 {
		return 0, fmt.Errorf("quantity must be at least one, got %d", quantity)
	}
	cost, err := p.CostOf(sku)
	if err != nil {
		return 0, err
	}
	// Discounts apply to the marked-up price, not the cost price.
	unit := cost * BaseMarkup * (1 - discounts[tier])
	return math.Round(unit*float64(quantity)*100) / 100, nil
}

// PriceList returns every SKU with its unit price at a tier, in SKU order.
func (p *PriceBook) PriceList(tier Tier) ([][2]interface{}, error) {
	skus := make([]string, 0, len(p.costs))
	for sku := range p.costs {
		skus = append(skus, sku)
	}
	sort.Strings(skus)

	rows := make([][2]interface{}, 0, len(skus))
	for _, sku := range skus {
		price, err := p.Quote(sku, tier, 1)
		if err != nil {
			return nil, err
		}
		rows = append(rows, [2]interface{}{sku, price})
	}
	return rows, nil
}

// FormatMoney renders an amount with the currency suffix.
func FormatMoney(amount float64) string {
	return fmt.Sprintf("%.2f %s", amount, Currency)
}

// Package warehouse: reporting helpers over inventory and pricing.
package warehouse

import (
	"fmt"
	"strings"
)

// ReportWidth is the fixed width of a rendered report.
const ReportWidth = 72

// Separator rules off the report header and footer.
var Separator = strings.Repeat("-", ReportWidth)

// ReportError reports that a report could not be produced from the data.
type ReportError struct {
	Missing []string
}

// Error implements the error interface.
func (e *ReportError) Error() string {
	return fmt.Sprintf(
		"no cost price for %d SKUs: %s",
		len(e.Missing),
		strings.Join(e.Missing, ", "),
	)
}

// StockValue totals the quoted value of everything due for reorder.
func StockValue(inv *Inventory, prices *PriceBook, tier Tier) (float64, error) {
	rows, err := inv.ReorderList()
	if err != nil {
		return 0, err
	}
	total := 0.0
	for _, item := range rows {
		line, err := prices.Quote(item.SKU, tier, item.Quantity)
		if err != nil {
			return 0, fmt.Errorf("cannot value %s: %w", item.SKU, err)
		}
		total += line
	}
	return total, nil
}

// ReorderReport renders a plain-text reorder report.
func ReorderReport(inv *Inventory, prices *PriceBook) (string, error) {
	rows, err := inv.ReorderList()
	if err != nil {
		return "", err
	}
	if len(rows) == 0 {
		return "nothing to reorder\n", nil
	}

	lines := []string{fmt.Sprintf("reorder report for %s", inv.Warehouse), Separator}
	running := 0.0
	for _, item := range rows {
		// Trade pricing is what the purchasing team actually pays.
		lineTotal, err := prices.Quote(item.SKU, TierTrade, item.Quantity)
		if err != nil {
			return "", err
		}
		running += lineTotal
		lines = append(lines, formatRow(item, lineTotal))
	}
	lines = append(lines, Separator)
	lines = append(lines, fmt.Sprintf("%-22s%s", "total", FormatMoney(running)))
	return strings.Join(lines, "\n") + "\n", nil
}

func formatRow(item Item, lineTotal float64) string {
	sku := fmt.Sprintf("%-16s", item.SKU)
	quantity := fmt.Sprintf("%6d", item.Quantity)
	return sku + quantity + "  " + FormatMoney(lineTotal)
}

// CheckReportInputs fails loudly when a report would silently under-report.
func CheckReportInputs(inv *Inventory, prices *PriceBook) error {
	rows, err := inv.ReorderList()
	if err != nil {
		return err
	}
	var missing []string
	for _, item := range rows {
		if _, err := prices.CostOf(item.SKU); err != nil {
			missing = append(missing, item.SKU)
		}
	}
	if len(missing) > 0 {
		return &ReportError{Missing: missing}
	}
	return nil
}

